def transforms(S,n=9):
 out=[]
 for k in range(4):
  for flip in [False,True]:
   t=set()
   for r,c in S:
    if flip:c=n-1-c
    for _ in range(k): r,c=c,n-1-r
    t.add((r,c))
   out.append((k,flip,t))
 return out
